-- Run once in Supabase Dashboard -> SQL Editor (after 001).
-- Safe to run again: re-running updates the questions instead of duplicating.
-- Seeded from FirstApp/src/data/questions.ts (100 questions).

create table if not exists public.questions (
  id bigint generated by default as identity primary key,
  question text not null unique,
  options text[] not null,
  correct_index smallint not null,   -- 0 = first option, 1 = second, ...
  topic text not null,
  difficulty text not null,
  created_at timestamptz not null default now(),
  constraint questions_options_check
    check (array_length(options, 1) between 2 and 6),
  constraint questions_correct_index_check
    check (correct_index >= 0 and correct_index < array_length(options, 1)),
  constraint questions_difficulty_check
    check (difficulty in ('Easy', 'Medium', 'Hard'))
);

create index if not exists questions_topic_difficulty_idx
  on public.questions (topic, difficulty);

-- RLS on with NO policies: the app and logged-in users can't read this
-- table directly (it contains the correct answers). Only the backend can,
-- using the secret key, and it never sends correct_index to the app.
alter table public.questions enable row level security;
revoke all on public.questions from anon, authenticated;

