  question = excluded.question,
  options = excluded.options,
  correct_index = excluded.correct_index,
  topic = excluded.topic,
  difficulty = excluded.difficulty;

-- New questions added later get IDs after the seeded ones.
select setval(
  pg_get_serial_sequence('public.questions', 'id'),
  (select max(id) from public.questions)
);

notify pgrst, 'reload schema';

-- Check: how many questions per topic and difficulty
select topic, difficulty, count(*) as questions
from public.questions
group by topic, difficulty
order by topic, difficulty;
